def ja_parts(a):
    """ja本文の冒頭<h2>【日本語版】…</h2>からタイトルを取り出し、本文と分離する"""
    m = re.match(r"\s*<h2>【日本語版】(.*?)</h2>", a["ja"])
    title = m.group(1)
    body = a["ja"][m.end():]
    return title, body

def related_block(slug, lang):
    """記事末尾の関連記事リンク（同一ディレクトリ内の相対リンク）"""
    by_slug = {a["slug"]: a for a in ARTICLES}
    items = ""
    for s in RELATED.get(slug, []):
        ra = by_slug[s]
        label_title = ra["title"] if lang == "zh" else ja_parts(ra)[0]
        items += f'<li><a href="{s}.html">{label_title}</a></li>\n'
    if not items:
        return ""
    label = "相關文章" if lang == "zh" else "関連記事"
    return f'<div class="related"><div class="label">{label}</div><ul>\n{items}</ul></div>'


FS_INIT = """<script>(function(){var v=localStorage.getItem('bsfs');if(v)document.documentElement.style.fontSize=v+'%';})();</script>"""
FS_JS = """<script>
(function(){
  var btns=document.querySelectorAll('.fontsize button');if(!btns.length)return;
  function apply(v,save){
    document.documentElement.style.fontSize=(v==='100'?'':v+'%');
    btns.forEach(function(b){b.classList.toggle('active',b.getAttribute('data-fs')===v);});
    if(save)localStorage.setItem('bsfs',v);
  }
  btns.forEach(function(b){b.addEventListener('click',function(){apply(b.getAttribute('data-fs'),true);});});
  apply(localStorage.getItem('bsfs')||'100',false);
})();
</script>"""

THEME_INIT = """<script>(function(){if(localStorage.getItem('bstheme')==='dark')document.documentElement.setAttribute('data-theme','dark');})();</script>"""
THEME_JS = """<script>
(function(){
  var b=document.querySelector('.theme-toggle');if(!b)return;
  b.addEventListener('click',function(){
    if(document.documentElement.getAttribute('data-theme')==='dark'){
      document.documentElement.removeAttribute('data-theme');localStorage.removeItem('bstheme');
    }else{
      document.documentElement.setAttribute('data-theme','dark');localStorage.setItem('bstheme','dark');
    }
  });
})();
</script>"""
TOC_JS = """<script>
(function(){
  var art=document.querySelector('article.post');if(!art)return;
  function pick(sel){return Array.prototype.filter.call(art.querySelectorAll(sel),function(h){return !h.closest('.related');});}
  var hs=pick('h2');if(hs.length<3)hs=pick('h3');if(hs.length<3)return;
  var ja=document.documentElement.lang==='ja';
  var items='';
  hs.forEach(function(h,i){if(!h.id)h.id='sec'+(i+1);items+='<li><a href="#'+h.id+'"></a></li>';});
  var toc=document.createElement('nav');toc.className='toc';
  toc.innerHTML='<div class="label">'+(ja?'目次':'目錄')+'</div><ol>'+items+'</ol>';
  var links=toc.querySelectorAll('a');
  hs.forEach(function(h,i){links[i].textContent=h.textContent;});
  var ref=art.querySelector('.tldr')||art.querySelector('.lang-note')||art.querySelector('.date');
  if(ref)ref.insertAdjacentElement('afterend',toc);
})();
</script>"""

def page(title, desc, body, root="", alt="", lang="zh"):
    head = HEAD if lang == "zh" else HEAD_JA
    foot = FOOT if lang == "zh" else FOOT_JA
    h = head.format(title=html.escape(title), desc=html.escape(desc), root=root, alt=alt, threads=THREADS, youtube=YOUTUBE)
    h = h.replace("</head>", FS_INIT + THEME_INIT + "\n</head>")
    f = foot.format(root=root, threads=THREADS, youtube=YOUTUBE)
    f = f.replace("</body>", FS_JS + THEME_JS + TOC_JS + "\n</body>")
    return h + body + f

def card_zh(a):
    return f"""<a class="card catc-{CAT_SLUG[a['cat']]}" href="articles/{a['slug']}.html">
<div class="cat">{a['cat']}</div>
<h3>{a['title']}</h3>
<p>{a['summary']}</p>
<div class="date">{a['date']}</div>
</a>\n"""

def card_ja(a):
    t, _ = ja_parts(a)
    return f"""<a class="card catc-{CAT_SLUG[a['cat']]}" href="articles/{a['slug']}.html">
<div class="cat">{CAT_JA[a['cat']]}</div>
<h3>{t}</h3>
<p>{JA_SUMMARY[a['slug']]}</p>
<div class="date">{a['date']}</div>
</a>\n"""

def catnav(arts, lang, active=None):
    """カテゴリナビ（件数付き）。index・カテゴリページ共通。root直下からの相対リンク"""
    links = []
    all_label = "全部文章" if lang == "zh" else "すべての記事"
    cls = ' class="active"' if active is None else ""
    idx = "index.html#articles" if lang == "zh" else "index.html#articles"
    links.append(f'<a{cls} href="{idx}">{all_label}（{len(arts)}）</a>')
    for cat, cslug in CAT_SLUG.items():
        n = sum(1 for a in arts if a["cat"] == cat)
        label = cat if lang == "zh" else CAT_JA[cat]
        cls = ' class="active"' if active == cat else ""
        links.append(f'<a{cls} href="category-{cslug}.html">{label}（{n}）</a>')
    return '<div class="catnav">' + "\n".join(links) + "</div>"

